import socket
import ipaddress
import urllib.request
import urllib.parse
import ssl
import json
import hashlib
import hmac
import time
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Optional, Tuple, Dict

# Configuration
ALLOWED_SCHEMES = ('http', 'https')
MAX_RESPONSE_SIZE = 1024 * 1024  # 1MB
REQUEST_TIMEOUT = 5
HMAC_SECRET = os.environ.get('HMAC_SECRET', 'default-secret-key-change-me').encode()

# Internal network ranges that should never be accessed
BLOCKED_RANGES = [
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('169.254.0.0/16'),
    ipaddress.ip_network('::1/128'),
    ipaddress.ip_network('fc00::/7'),
    ipaddress.ip_network('fe80::/10'),
]


def _is_ip_blocked(ip_str: str) -> bool:
    """Check if an IP address falls within blocked ranges."""
    try:
        addr = ipaddress.ip_address(ip_str)
        for network in BLOCKED_RANGES:
            if addr in network:
                return True
        return False
    except ValueError:
        return True  # Block invalid IPs


def _validate_url_scheme(url: str) -> bool:
    """Ensure URL uses an allowed scheme."""
    parsed = urllib.parse.urlparse(url)
    return parsed.scheme in ALLOWED_SCHEMES


def _resolve_and_validate_host(hostname: str) -> Tuple[bool, Optional[str]]:
    """Resolve hostname and validate the IP is not in blocked ranges.

    Returns (is_safe, resolved_ip) tuple.
    Uses the system DNS resolver to check where the hostname points.
    """
    try:
        # Resolve all addresses for the hostname
        addr_infos = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM)

        if not addr_infos:
            return (False, None)

        # Check ALL resolved IPs - if any are blocked, reject
        resolved_ips = set()
        for family, socktype, proto, canonname, sockaddr in addr_infos:
            ip = sockaddr[0]
            resolved_ips.add(ip)
            if _is_ip_blocked(ip):
                return (False, None)

        # Return the first resolved IP for logging
        first_ip = next(iter(resolved_ips))
        return (True, first_ip)
    except (socket.gaierror, socket.herror, OSError):
        return (False, None)


def _generate_request_signature(url: str, timestamp: int) -> str:
    """Generate HMAC signature for request audit trail."""
    message = f"{url}|{timestamp}".encode()
    return hmac.new(HMAC_SECRET, message, hashlib.sha256).hexdigest()


def _verify_request_signature(url: str, timestamp: int, signature: str) -> bool:
    """Verify the HMAC signature of a request."""
    expected = _generate_request_signature(url, timestamp)
    return hmac.compare_digest(expected, signature)


class URLFetchService:
    """Service that fetches URLs on behalf of users with SSRF protection.

    Security model:
    1. Only HTTP/HTTPS schemes allowed
    2. DNS resolution performed to check destination IP
    3. All private/internal IP ranges blocked
    4. Response size limited
    5. Request timeout enforced
    6. Audit logging with HMAC signatures
    """

    def __init__(self):
        self._request_log: Dict[str, dict] = {}
        self._rate_limiter: Dict[str, list] = {}
        self._max_requests_per_minute = 10

    def _check_rate_limit(self, client_id: str) -> bool:
        """Simple sliding window rate limiter."""
        now = time.time()
        if client_id not in self._rate_limiter:
            self._rate_limiter[client_id] = []

        # Remove old entries
        self._rate_limiter[client_id] = [
            t for t in self._rate_limiter[client_id]
            if now - t < 60
        ]

        if len(self._rate_limiter[client_id]) >= self._max_requests_per_minute:
            return False

        self._rate_limiter[client_id].append(now)
        return True

    def fetch_url(self, url: str, client_id: str) -> dict:
        """Fetch a URL with full SSRF protection.

        The security check flow:
        1. Validate URL scheme
        2. Parse and extract hostname
        3. Resolve hostname to IP via DNS
        4. Verify resolved IP is not in blocked ranges
        5. If all checks pass, make the HTTP request
        """
        # Rate limiting
        if not self._check_rate_limit(client_id):
            return {'error': 'Rate limit exceeded', 'status': 429}

        # Step 1: Scheme validation
        if not _validate_url_scheme(url):
            return {'error': 'Invalid URL scheme', 'status': 400}

        # Step 2: Parse URL and extract hostname
        parsed = urllib.parse.urlparse(url)
        hostname = parsed.hostname

        if not hostname:
            return {'error': 'No hostname in URL', 'status': 400}

        # Step 3 & 4: DNS resolution and IP validation
        is_safe, resolved_ip = _resolve_and_validate_host(hostname)

        if not is_safe:
            return {'error': 'Blocked destination', 'status': 403}

        # Step 5: Make the actual HTTP request
        # Note: We've validated the DNS resolution above, but we make
        # the request using the original URL to preserve Host headers
        # and virtual hosting compatibility.
        try:
            ctx = ssl.create_default_context()
            req = urllib.request.Request(url, headers={
                'User-Agent': 'URLFetchService/1.0',
                'Accept': 'text/html,application/json',
            })

            response = urllib.request.urlopen(
                req, timeout=REQUEST_TIMEOUT, context=ctx
            )

            # Read with size limit
            data = response.read(MAX_RESPONSE_SIZE)
            content_type = response.headers.get('Content-Type', 'unknown')
            status_code = response.status

            # Audit log
            timestamp = int(time.time())
            signature = _generate_request_signature(url, timestamp)
            self._request_log[signature] = {
                'url': url,
                'client_id': client_id,
                'resolved_ip': resolved_ip,
                'timestamp': timestamp,
                'status': status_code,
            }

            return {
                'status': status_code,
                'content_type': content_type,
                'body': data.decode('utf-8', errors='replace')[:4096],
                'resolved_ip': resolved_ip,
                'audit_signature': signature,
            }

        except urllib.error.HTTPError as e:
            return {'error': f'HTTP error: {e.code}', 'status': e.code}
        except urllib.error.URLError as e:
            return {'error': f'URL error: {str(e.reason)}', 'status': 502}
        except Exception as e:
            return {'error': 'Request failed', 'status': 500}

    def get_audit_log(self, signature: str) -> Optional[dict]:
        """Retrieve audit log entry by signature."""
        return self._request_log.get(signature)


class WebhookHandler(BaseHTTPRequestHandler):
    """HTTP handler for the URL fetch webhook service."""

    service = URLFetchService()

    def do_POST(self):
        if self.path == '/fetch':
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length > 4096:
                self._send_json({'error': 'Request too large'}, 413)
                return

            body = self.rfile.read(content_length)
            try:
                request = json.loads(body)
            except json.JSONDecodeError:
                self._send_json({'error': 'Invalid JSON'}, 400)
                return

            url = request.get('url', '')
            client_id = request.get('client_id', 'anonymous')

            if not url or not isinstance(url, str):
                self._send_json({'error': 'Missing or invalid url'}, 400)
                return

            result = self.service.fetch_url(url, client_id)
            self._send_json(result, result.get('status', 200))
        else:
            self._send_json({'error': 'Not found'}, 404)

    def _send_json(self, data: dict, status: int = 200):
        response = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.end_headers()
        self.wfile.write(response)

    def log_message(self, format, *args):
        pass  # Suppress default logging


if __name__ == '__main__':
    port = int(os.environ.get('PORT', '8080'))
    server = HTTPServer(('127.0.0.1', port), WebhookHandler)
    print(f'URLFetchService listening on port {port}')
    server.serve_forever()
